const cfg = $('Config').first().json;
const staticData = $getWorkflowStaticData('global');
staticData.seen = staticData.seen || {};

function parsePriceToMonthly(priceText) {
  const t = String(priceText || '');
  const m = t.replace(/,/g, '').match(/€\s?(\d+(?:\.\d+)?)/);
  if (!m) return null;
  const n = Number(m[1]);
  if (!Number.isFinite(n)) return null;
  if (/week/i.test(t)) return Math.round(n * 52 / 12);
  return Math.round(n);
}
function bedsNum(v) {
  const m = String(v || '').match(/(\d+)/);
  return m ? Number(m[1]) : 0;
}
function htmlOf(item) {
  const j = item.json;
  if (typeof j === 'string') return j;
  return j.data || j.body || j.html || '';
}
function extractDaft(html, sourceUrl, sourceName) {
  const match = String(html).match(/<script[^>]*id="__NEXT_DATA__"[^>]*>(.*?)<\/script>/);
  if (!match) return [];
  let data; try { data = JSON.parse(match[1]); } catch(e) { return []; }
  const list = (((data || {}).props || {}).pageProps || {}).listings || [];
  const out = [];
  for (const row of list) {
    const L = row.listing || row;
    if (!L || !L.id) continue;
    const title = L.title || '';
    const path = L.seoFriendlyPath || '';
    const url = path ? `https://www.daft.ie${path}` : `https://www.daft.ie/for-rent/roscrea/${L.id}`;
    const blob = `${title} ${path} ${sourceUrl}`.toLowerCase();
    if (!blob.includes('roscrea')) continue;
    const monthly = parsePriceToMonthly(L.price);
    const beds = bedsNum(L.numBedrooms);
    if (Number(cfg.maxMonthlyEuro) > 0 && monthly && monthly > Number(cfg.maxMonthlyEuro)) continue;
    if (Number(cfg.minBeds) > 0 && beds > 0 && beds < Number(cfg.minBeds)) continue;
    out.push({
      id: `daft-${L.id}`,
      source: sourceName || 'daft',
      title,
      price: L.price || '',
      monthly,
      beds: L.numBedrooms || '',
      baths: L.numBathrooms || '',
      propertyType: L.propertyType || '',
      seller: (L.seller && L.seller.name) || '',
      sellerType: (L.seller && L.seller.sellerType) || '',
      url
    });
  }
  return out;
}
function extractMyHome(html, sourceName) {
  const text = String(html);
  if (/No homes listed here yet/i.test(text)) return [];
  const abs = [...text.matchAll(/https?:\/\/www\.myhome\.ie\/[^"'\\\s<>]+/g)].map(m => m[0].replace(/&amp;/g,'&'));
  const rel = [...text.matchAll(/href=\"(\/rentals\/[^\"]+)\"/g)].map(m => 'https://www.myhome.ie' + m[1].replace(/&amp;/g,'&'));
  const all = [...new Set([...abs, ...rel])]
    .filter(u => !u.includes('house-to-rent-in-roscrea') && !u.includes('apartment-to-rent-in-roscrea'))
    .filter(u => /\/\d{4,}/.test(u) || /property|residential|rental/i.test(u));
  const out = [];
  for (const url of all.slice(0, 30)) {
    out.push({
      id: `myhome-${url}`,
      source: sourceName || 'myhome',
      title: 'MyHome Roscrea rental',
      price: '',
      monthly: null,
      beds: '',
      baths: '',
      propertyType: '',
      seller: '',
      sellerType: '',
      url
    });
  }
  return out;
}

const urlItems = $('Split Sources').all();
const found = [];
const batch = new Set();
for (let i = 0; i < items.length; i++) {
  const meta = (urlItems[i] && urlItems[i].json) || {};
  const html = htmlOf(items[i]);
  const sourceUrl = meta.url || '';
  const source = meta.source || 'unknown';
  let list = [];
  if (String(source).startsWith('daft')) list = extractDaft(html, sourceUrl, source);
  else if (String(source).startsWith('myhome')) list = extractMyHome(html, source);
  for (const L of list) {
    if (batch.has(L.id) || staticData.seen[L.id]) continue;
    batch.add(L.id);
    found.push({ json: { ...cfg, ...L } });
  }
}
return found;

const staticData = $getWorkflowStaticData('global');
staticData.seen = staticData.seen || {};
const cfg = $('Config').first().json;

const candidate = $('Has Candidates?').item.json;
const htmlRaw = items[0].json;
const html = typeof htmlRaw === 'string' ? htmlRaw : (htmlRaw.data || htmlRaw.body || htmlRaw.html || htmlRaw.verifyHtml || '');

function unavailable(html) {
  const t = String(html || '');
  if (!t || t.length < 200) return true;
  if (/no longer available|this ad has been removed|ad has expired|property is no longer available|removed by the advertiser/i.test(t)) return true;
  const m = t.match(/<script[^>]*id="__NEXT_DATA__"[^>]*>(.*?)<\/script>/);
  if (m) {
    try {
      const data = JSON.parse(m[1]);
      const listing = (((data || {}).props || {}).pageProps || {}).listing;
      if (listing && listing.state && String(listing.state).toUpperCase() !== 'PUBLISHED') return true;
      // enrich from detail page if possible
      if (listing) {
        candidate.title = listing.title || candidate.title;
        candidate.price = listing.price || candidate.price;
        candidate.seller = (listing.seller && listing.seller.name) || candidate.seller;
        candidate.beds = listing.numBedrooms || candidate.beds;
        candidate.propertyType = listing.propertyType || candidate.propertyType;
        if (listing.seoFriendlyPath) candidate.url = `https://www.daft.ie${listing.seoFriendlyPath}`;
      }
    } catch (e) {}
  }
  if (/No homes listed here yet/i.test(t) && candidate.source.startsWith('myhome')) return true;
  return false;
}

if (unavailable(html)) {
  // mark as seen dead so we don't recheck forever every 2 min? better mark dead
  staticData.seen[candidate.id] = Date.now();
  return [];
}

// available + new
staticData.seen[candidate.id] = Date.now();

// keep map small
const entries = Object.entries(staticData.seen).sort((a,b)=>b[1]-a[1]);
if (entries.length > 800) staticData.seen = Object.fromEntries(entries.slice(0,800));

function monthly(priceText) {
  const t = String(priceText || '');
  const m = t.replace(/,/g,'').match(/€\s?(\d+(?:\.\d+)?)/);
  if (!m) return candidate.monthly || null;
  const n = Number(m[1]);
  if (/week/i.test(t)) return Math.round(n*52/12);
  return Math.round(n);
}
const mon = monthly(candidate.price);

const text = [
  `🚨 ROSCREA LIVE RENTAL`,
  ``,
  `📍 ${candidate.title}`,
  `💶 ${candidate.price || 'Price on ad'}${mon ? ` (~€${mon}/mo)` : ''} · ${candidate.beds || '? bed'} · ${candidate.propertyType || ''}`.trim(),
  `👤 ${candidate.seller || 'Contact on ad'}`,
  `🟢 Status: AVAILABLE NOW`,
  `📡 Source: ${candidate.source}`,
  ``,
  `🔗 ${candidate.url}`,
  ``,
  `ACTION NOW:`,
  `1) Open link`,
  `2) Call if phone visible`,
  `3) Else Enquire immediately`,
  ``,
  `Script:`,
  `Hi, I'm interested in the Roscrea rental.`,
  `Is it still available for a viewing this week?`
].join('\n');

return [{
  json: {
    ...candidate,
    monthly: mon,
    telegramChatId: cfg.telegramChatId,
    sheetId: cfg.sheetId,
    status: 'available',
    foundAt: new Date().toISOString(),
    text
  }
}];

const sheetId=String($json.sheetId||'').trim();
if(!sheetId) return [];
return items;
